        new={'TL':val['BL'],'TR':val['TL'],'BR':val['TR'],'BL':val['BR']}
        dirs={'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}
        for k,p in corners.items():
            if 0<=p[0]<H and 0<=p[1]<W: g[p[0]][p[1]]=new[k]
